<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref} from 'vue'
import {Check,ChevronRight,Clock3,LockKeyhole,Radio,RefreshCw,Router,Save,ShieldCheck,Signal,Users,Wifi,X} from '@lucide/vue'
import {api,type Observation,type Summary} from '../services/api'
import WifiTraffic from './WifiTraffic.vue'
import UplinkMode from './UplinkMode.vue'
import {trafficInteger,trafficVolume} from '../services/traffic'
import '../wifi-ap-page.css'
type Network={id:number;ssid:string;current:boolean;disabled:boolean;managed:boolean}
type Saved={id:string;ssid:string;security:string;passwordConfigured:boolean}
type Transaction={id:string;state:string;expiresAt:string;targetSSID:string;canConfirm:boolean;reason?:string}
type WiFiView={status:{state:string;ssid:string;networkID:number|null;ipv4:string};networks:Network[];saved:Saved[];transaction:Transaction|null}
type Scan={ssid:string;bssid:string;frequency:number;signalDBm:number;security:string}
type Preference='cellular'|'wifi'
type Sharing={preference?:Preference;enabled:boolean;state:string;ready:boolean;dnsReady:boolean;upstream?:{kind:string;interface:string};errorCode?:string}
type AP={sharing?:Sharing;settings:{revision:number;enabled:boolean;ssid:string;passphraseConfigured:boolean;preference?:Preference};enabled:boolean|null;dhcpReady:boolean|null;address:string;channel?:number;clientCount:number|null;clients?:{mac:string;ipv4?:string;hostname?:string;signalDBm?:number;receivedBytes?:string;sentBytes?:string}[];worker?:{state:string;errorCode?:string}}
const props=defineProps<{summary:Summary}>(),emit=defineEmits<{refresh:[]}>()
const wifi=ref<WiFiView>(),ap=ref<Observation<AP>>(),networks=ref<Scan[]>([]),busy=ref(false),scanning=ref(false),error=ref(''),message=ref(''),loadError=ref(''),apError=ref(''),apMessage=ref(''),apBusy=ref(false),ssid=ref(''),security=ref('wpa2'),password=ref(''),apSSID=ref(''),apPassword=ref(''),apEnabled=ref(false),now=ref(Date.now())
let active=true,poll:ReturnType<typeof setInterval>|undefined,tick:ReturnType<typeof setInterval>|undefined,inFlight=false,apInstalled=false
const pending=computed(()=>wifi.value?.transaction?.state==='pending'?wifi.value.transaction:undefined)
const remaining=computed(()=>pending.value?Math.max(0,Math.ceil((Date.parse(pending.value.expiresAt)-now.value)/1000)):0)
const connected=computed(()=>wifi.value?.status.state==='COMPLETED')
const apData=computed(()=>ap.value?.data)
const nearby=computed(()=>networks.value.filter((network,index,all)=>all.findIndex(item=>item.ssid===network.ssid&&item.security===network.security)===index).sort((a,b)=>b.signalDBm-a.signalDBm))
function jump(section:string){document.getElementById(section)?.scrollIntoView({behavior:'smooth',block:'start'})}
function reason(e:unknown){const value=e instanceof Error?e.message:String(e);if(value.includes('WIFI_TARGET_NOT_CONNECTED'))return '接続先との通信をまだ確認できません。接続状態を確認してから、もう一度確定してください。';if(value.includes('WIFI_TRANSACTION_PENDING'))return '接続確認中です。現在の接続を確定するか、元に戻してください。';if(value.includes('WIFI_CONNECTION_INVALID'))return 'SSIDと認証設定を確認してください。WPA2のパスワードは8〜63文字、または64桁の16進数です。';if(value.includes('REVISION_CONFLICT'))return '別の操作で設定が変わりました。最新状態を読み直してください。';if(value.includes('WIFI_ROLLBACK'))return '元のWi-Fiへの復旧を確認できません。ホットスポットまたはUSB接続から状態を確認してください。';if(value.includes('WIFI_CONTROL_UNAVAILABLE'))return 'Wi-Fi制御へ接続できません。';return value}
function installAP(value:Observation<AP>,force=false){ap.value=value;if((!apInstalled||force)&&value.data?.settings){apSSID.value=value.data.settings.ssid;apEnabled.value=value.data.settings.enabled;apPassword.value='';apInstalled=true}}
async function load(){if(inFlight||!active)return;inFlight=true;try{const results=await Promise.allSettled([api<WiFiView>('/network/wifi/networks'),api<Observation<AP>>('/network/hotspot')]);if(!active)return;if(results[0].status==='fulfilled'){wifi.value=results[0].value;loadError.value=''}else loadError.value=reason(results[0].reason);if(results[1].status==='fulfilled')installAP(results[1].value);else if(!ap.value)apError.value=reason(results[1].reason)}finally{inFlight=false}}
async function scan(){if(scanning.value)return;scanning.value=true;error.value='';try{const result=await api<{scanRequested:boolean;results:Scan[]}>('/network/wifi/scan','POST',{});if(active){networks.value=result.results;message.value='再検索を要求しました。直近の検出結果を表示しています。'}}catch(e){if(active)error.value=reason(e)}finally{if(active)scanning.value=false}}
function choose(network:Scan){ssid.value=network.ssid;security.value=network.security==='open'?'open':'wpa2';password.value='';message.value=''}
async function connect(body:Record<string,unknown>,saved=false){if(busy.value||pending.value)return;busy.value=true;error.value='';message.value='';try{const value=await api<Transaction>('/network/wifi/'+(saved?'connect-saved':'connect-new'),'POST',body);if(active){if(value.state!=='pending')throw new Error('接続確認の開始を確認できません。');if(wifi.value)wifi.value.transaction=value;password.value='';await load()}}catch(e){if(active)error.value=reason(e)}finally{if(active)busy.value=false}}
async function finish(confirm:boolean){if(!pending.value||busy.value)return;busy.value=true;error.value='';message.value='';try{const value=await api<Transaction>('/network/wifi/'+(confirm?'confirm':'rollback'),'POST',{transactionID:pending.value.id});if(active){if(value.state!==(confirm?'confirmed':'rolled-back'))throw new Error('操作の完了を確認できません。');message.value=confirm?'Wi-Fi接続を確定しました。':'元のWi-Fi接続へ戻しました。';if(wifi.value)wifi.value.transaction=value;await load();emit('refresh')}}catch(e){if(active)error.value=reason(e)}finally{if(active)busy.value=false}}
async function saveAP(){if(!apData.value?.settings||apBusy.value||pending.value)return;apBusy.value=true;apError.value='';apMessage.value='';const expectedEnabled=apEnabled.value,expectedSSID=apSSID.value;try{const value=await api<Observation<AP>>('/network/hotspot','PUT',{expectedRevision:apData.value.settings.revision,settings:{enabled:expectedEnabled,ssid:expectedSSID,...(apPassword.value?{passphrase:apPassword.value}:{})}});if(active){if(value.data?.enabled!==expectedEnabled||value.data?.settings?.ssid!==expectedSSID||expectedEnabled&&value.data?.dhcpReady!==true)throw new Error('ホットスポットの反映を確認できません。');installAP(value,true);apMessage.value='ホットスポットの反映を確認しました。';emit('refresh')}}catch(e){if(active)apError.value=reason(e)}finally{if(active)apBusy.value=false}}
onMounted(()=>{load();poll=setInterval(load,2000);tick=setInterval(()=>{now.value=Date.now()},1000)})
onUnmounted(()=>{active=false;clearInterval(poll);clearInterval(tick);password.value='';apPassword.value=''})
</script>

<template>
 <div class="wifi-ap-page">
  <nav class="wifi-page-tabs" aria-label="接続設定へ移動"><button @click="jump('wifi-sta-settings')"><Wifi :size="15"/>Wi-Fi接続</button><button @click="jump('wifi-ap-settings')"><Router :size="15"/>ホットスポット</button></nav>
  <div v-if="loadError" class="banner error" role="alert">{{loadError}}</div>
  <section v-if="pending" class="wifi-confirmation" aria-labelledby="wifi-confirm-title"><div class="wifi-confirm-clock"><Clock3 :size="23"/><strong>{{remaining}}<small>秒</small></strong></div><div><h2 id="wifi-confirm-title">このWi-Fi接続を使いますか？</h2><p><b>{{pending.targetSSID}}</b> への接続を確認してください。時間内に確定しない場合は、元の接続へ自動で戻します。</p><span>{{pending.canConfirm?'接続先を確認できました':'接続先を確認しています…'}}</span></div><div class="wifi-confirm-actions"><button class="primary" :disabled="busy||!pending.canConfirm||remaining===0" @click="finish(true)"><Check :size="16"/>この接続を使う</button><button class="secondary" :disabled="busy" @click="finish(false)">元に戻す</button></div></section>
  <div v-if="error" class="banner error" role="alert">{{error}}</div><div v-if="message" class="banner success" role="status">{{message}}</div>
  <UplinkMode/>
  <section id="wifi-sta-settings" class="panel wifi-sta"><header class="wifi-section-head"><div><h2><Wifi :size="21"/>Wi-Fi接続</h2><p>NP1からインターネットへ接続するWi-Fiを選びます。</p></div><button class="icon-button" aria-label="Wi-Fi状態を更新" @click="load"><RefreshCw :size="17"/></button></header><div class="wifi-current"><div class="wifi-current-icon" :class="{online:connected}"><Wifi :size="27"/></div><div><span>{{connected?'接続中':wifi?.status.state==='SCANNING'?'接続先を検索中':wifi?'未接続':'状態を確認中'}}</span><h3>{{wifi?.status.ssid||'接続先未選択'}}</h3><p>IPアドレス <b>{{wifi?.status.ipv4||'未取得'}}</b></p></div><WifiTraffic :summary="summary"/></div>
   <div class="wifi-connect-layout"><div class="wifi-network-list"><div class="wifi-list-head"><h3>接続先を選ぶ</h3><button class="secondary compact" :disabled="scanning||busy||!!pending" @click="scan"><RefreshCw :size="14"/>{{scanning?'検索中…':'周辺を検索'}}</button></div><p class="wifi-list-note">直近の検出結果</p><div v-if="!nearby.length" class="wifi-empty">周辺を検索するか、右の入力欄から接続してください。</div><button v-for="network in nearby" :key="network.ssid+network.security" class="wifi-network" :disabled="busy||!!pending||network.security==='unsupported'" @click="choose(network)"><Signal :size="18"/><span><strong>{{network.ssid}}</strong><small>{{network.security==='open'?'認証なし':network.security==='wpa2'?'WPA2 Personal':'未対応の認証方式'}} · {{network.signalDBm}} dBm</small></span><LockKeyhole v-if="network.security!=='open'" :size="14"/><ChevronRight :size="15"/></button>
    <template v-if="wifi?.networks.length"><h3 class="wifi-saved-heading">本体が保持している接続先</h3><button v-for="network in wifi.networks" :key="network.id" class="wifi-network" :disabled="busy||!!pending||network.current" @click="connect({networkID:network.id},true)"><Wifi :size="17"/><span><strong>{{network.ssid||'非公開SSID'}}</strong><small>{{network.current?'接続中':network.managed?'NCC管理の接続先':'本体の接続先'}}</small></span><Check v-if="network.current" :size="16"/><ChevronRight v-else :size="15"/></button></template>
    <template v-if="wifi?.saved.length"><h3 class="wifi-saved-heading">NCCに保存した接続先</h3><button v-for="profile in wifi.saved" :key="profile.id" class="wifi-network" :disabled="busy||!!pending" @click="connect({profileID:profile.id},true)"><Save :size="17"/><span><strong>{{profile.ssid}}</strong><small>{{profile.security==='open'?'認証なし':'パスワード保存済み'}}</small></span><ChevronRight :size="15"/></button></template>
   </div><form class="wifi-connect-form" @submit.prevent="connect({ssid,security,password:security==='open'?'':password})"><h3>新しい接続先</h3><label>SSID<input v-model="ssid" autocomplete="off" spellcheck="false" maxlength="32" required :disabled="busy||!!pending" aria-label="接続先SSID"></label><label>認証方式<select v-model="security" :disabled="busy||!!pending" aria-label="Wi-Fi認証方式"><option value="wpa2">WPA2 Personal</option><option value="open">認証なし</option></select></label><label v-if="security==='wpa2'">パスワード<input v-model="password" type="password" autocomplete="new-password" maxlength="64" required :disabled="busy||!!pending" aria-label="Wi-Fi接続パスワード"></label><p><ShieldCheck :size="15"/>接続後90秒以内に確定するとNCCへ保存します。確認中に管理画面が切れた場合は、ホットスポットまたはTailscaleから開き直してください。</p><button class="primary" type="submit" :disabled="busy||!!pending||!ssid"><Wifi :size="16"/>{{busy?'接続操作中…':'このWi-Fiへ接続'}}</button></form></div>
  </section>

  <section id="wifi-ap-settings" class="panel wifi-ap"><header class="wifi-section-head"><div><h2><Router :size="21"/>ホットスポット</h2><p>スマートフォンやPCをつなぎ、NP1の通信回線を共有します。</p></div><span class="wifi-ap-state" :class="{online:apData?.enabled===true}">{{apData?.enabled===true?'稼働中':apData?.enabled===false?'停止中':'状態未取得'}}</span></header><div v-if="apError" class="wifi-ap-notice error" role="alert">{{apError}}</div><div v-if="apMessage" class="wifi-ap-notice" role="status">{{apMessage}}</div><div class="wifi-ap-layout"><form @submit.prevent="saveAP"><label class="wifi-toggle"><input v-model="apEnabled" type="checkbox" :disabled="apBusy||!!pending||!apInstalled">ホットスポットを有効にする</label><label>SSID<input v-model="apSSID" autocomplete="off" spellcheck="false" maxlength="32" :disabled="apBusy||!!pending||!apInstalled" aria-label="ホットスポットのSSID"></label><label>接続パスワード <small>{{apData?.settings?.passphraseConfigured?'保存済み':'未設定'}}</small><input v-model="apPassword" type="password" autocomplete="new-password" maxlength="63" :placeholder="apData?.settings?.passphraseConfigured?'変更する場合のみ入力':'8〜63文字の半角英数字・記号'" :disabled="apBusy||!!pending||!apInstalled" aria-label="ホットスポットのパスワード"></label><p class="wifi-form-note">空欄のまま保存すると、保存済みパスワードを保ちます。変更時は接続中の端末が切断されます。</p><button type="submit" class="primary" :disabled="apBusy||!!pending||!apInstalled"><Save :size="16"/>{{apBusy?'反映中…':'ホットスポットに反映'}}</button></form><aside><h3>接続の詳細</h3><dl><div><dt>インターネット共有</dt><dd>{{apData?.sharing?.ready?(apData.sharing.upstream?.kind==='cellular'?'4G経由':'Wi-Fi経由'):apData?.sharing?.state==='error'?'共有を確認できません':apData?.enabled?'上流接続待ち':'停止中'}}</dd></div><div><dt>管理画面</dt><dd>{{apData?.address||'未取得'}}</dd></div><div><dt>チャンネル</dt><dd>{{apData?.channel??'未取得'}}</dd></div><div><dt>アドレス配布</dt><dd>{{apData?.dhcpReady===true?'利用可能':apData?.dhcpReady===false?'停止中':'未取得'}}</dd></div><div><dt>接続端末</dt><dd>{{typeof apData?.clientCount==='number'?apData.clientCount+' 台':'未取得'}}</dd></div></dl><p><Radio :size="15"/>{{apData?.sharing?.ready?(apData.sharing.upstream?.kind==='cellular'?'4G回線を共有しています。':'Wi-Fi接続を共有しています。'):apData?.enabled?'上流の接続を待っています。ホットスポットへの接続は継続できます。':'有効にすると、利用可能な回線を共有します。'}}</p><p v-if="pending">Wi-Fiの接続確認中は、ホットスポットの変更を待ってください。</p></aside></div>
   <div class="wifi-ap-clients"><h3><Users :size="18"/>接続端末</h3><div v-if="apData?.clients?.length" class="wifi-client-list"><div v-for="client in apData.clients" :key="client.mac"><span><strong>{{client.hostname||'接続端末'}}</strong><small>{{client.mac}}</small></span><span>{{client.ipv4||'IP未取得'}}</span><span>{{typeof client.signalDBm==='number'?client.signalDBm+' dBm':''}}</span><span class="wifi-client-traffic"><small>↓ 受信 <b>{{trafficVolume(trafficInteger(client.receivedBytes))}}</b></small><small>↑ 送信 <b>{{trafficVolume(trafficInteger(client.sentBytes))}}</b></small></span></div></div><p v-if="apData?.clients?.length" class="wifi-client-note">接続中のWi-Fi通信量（再接続でリセット）</p><p v-else>{{apData?.clientCount===0?'接続している端末はありません。':'端末の詳細情報はまだ取得できていません。'}}</p></div>
  </section>
 </div>
</template>
